insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000004','ACSM','Currier et al. Resistance Training Prescription: An Overview of Reviews',2026,'https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/','2026-10-18','Progressive training; goal-sensitive loading and weekly volume.','Healthy-adult averages, mostly inexperienced participants; app defaults are not individual prescriptions.');
insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000005','JSCR','Kassiano et al. Does Varying Resistance Exercises Promote Superior Muscle Hypertrophy and Strength Gains?',2022,'https://pubmed.ncbi.nlm.nih.gov/35438660/','2026-10-18','Systematic variation while retaining exercise specificity.','Eight small studies in young men; does not validate arbitrary exercise rotation.');
insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000006','JSCR','Ramos-Campo et al. Efficacy of Split Versus Full-Body Resistance Training',2024,'https://pubmed.ncbi.nlm.nih.gov/38595233/','2026-10-18','Volume-equated split selection can reflect practical preferences.','No universal best split or evidence that six days is required.');
insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000007','NSCA','Lincoln, Ill and Ibrahim. Progressive Strategies for Teaching Fundamental Resistance Training Movement Patterns',2023,'https://www.nsca.com/education/articles/ptq/teaching-resistance-training-movement-patterns/','2026-10-18','Skill-appropriate progressions and movement proficiency.','Professional education; exercise descriptions and rankings are original app editorial guidance.');
insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000008','NSCA','Snarr and Batrakoulis. Types of Resistance Training Equipment',2025,'https://www.nsca.com/certification/nsca-cpt/essentials-of-personal-training--3rd-edition/excerpts/types-of-resistance-training-equipment/','2026-10-18','Equipment selection considers training status, proficiency, and preference.','Educational excerpt; machine setup varies and broad equipment categories do not prove availability.');
insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000009','BJSM','Currier et al. Resistance training prescription: systematic review and Bayesian network meta-analysis',2023,'https://bjsm.bmj.com/content/57/18/1211','2026-10-18','Multiple prescriptions work; heavier load emphasis for strength and multiset hypertrophy options.','Network rankings are not individual outcome guarantees.');
insert into public.evidence_sources(id,organization,title,publication_year,url,accessed_on,supported_guidance,limitations) values ('10000000-0000-4000-8000-000000000010','PLoS ONE','Baz-Valle et al. Exercise variation, muscle thickness, strength and motivation',2019,'https://doi.org/10.1371/journal.pone.0226989','2026-10-18','Variation can affect motivation alongside training adaptations.','Small short trial in trained men; similar observed changes do not prove equivalence.');
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000013','barbell-back-squat','Barbell back squat','squat',array['quadriceps','glutes']::text[],array['trunk']::text[],array['barbell']::text[],'external','Use a rack with safeties. Brace, sit down between your hips, then stand with control. Choose a comfortable depth. Record total bar weight.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000014','leg-press','Leg press','squat',array['quadriceps','glutes']::text[],array[]::text[],array['machine']::text[],'external','Confirm a leg press is available. Keep your back supported, lower within a controlled range, then press without snapping the knees straight. Record the same machine and loading convention.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000015','dumbbell-split-squat','Dumbbell split squat','squat',array['quadriceps','glutes']::text[],array['trunk']::text[],array['dumbbell']::text[],'per_implement','Take a stable split stance. Lower the rear knee toward the floor and push through the front foot to stand. Record reps per side and weight per dumbbell.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000016','dumbbell-floor-press','Dumbbell floor press','horizontal_push',array['chest']::text[],array['triceps','shoulders']::text[],array['dumbbell']::text[],'per_implement','Lie on the floor with knees bent. Lower until the upper arms gently meet the floor, then press up. Use a controlled setup. Record weight per dumbbell.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000017','barbell-bench-press','Barbell bench press','horizontal_push',array['chest']::text[],array['triceps','shoulders']::text[],array['barbell']::text[],'external','Use a bench and rack with safeties or appropriate spotting. Keep feet planted, lower the bar under control toward the chest, then press. Record total bar weight.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000018','lat-pulldown','Lat pulldown','vertical_pull',array['back']::text[],array['biceps']::text[],array['machine']::text[],'external','Secure the thigh pad. Pull the handle toward your upper chest without swinging or pulling behind your neck. Return with control. Record the same machine and handle.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000019','seated-leg-curl','Seated leg curl','knee_flexion',array['hamstrings']::text[],array[]::text[],array['machine']::text[],'external','Align knees with the machine pivot and secure the pads. Curl down within a comfortable range, then return slowly. Follow the machine setup instructions.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000020','dumbbell-lateral-raise','Dumbbell lateral raise','lateral_raise',array['shoulders']::text[],array[]::text[],array['dumbbell']::text[],'per_implement','Stand steadily with soft elbows. Raise the arms out to the sides toward shoulder height without swinging, then lower with control. Record weight per dumbbell.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000021','dumbbell-curl','Dumbbell curl','elbow_flexion',array['biceps']::text[],array[]::text[],array['dumbbell']::text[],'per_implement','Keep upper arms steady. Curl the dumbbells by bending the elbows, then lower with control. Avoid swinging. Record reps per side and weight per dumbbell.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000022','cable-triceps-pressdown','Cable triceps pressdown','elbow_extension',array['triceps']::text[],array[]::text[],array['machine']::text[],'external','Use a high cable attachment. Keep elbows near your sides and extend the arms downward without moving the shoulders. Return with control. Record the same pulley and attachment.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000023','standing-dumbbell-calf-raise','Standing dumbbell calf raise','calf',array['calves']::text[],array[]::text[],array['dumbbell']::text[],'per_implement','Stand on level ground with balanced footing. Raise the heels, pause briefly, and lower with control. Use stable support if needed. Record weight per dumbbell.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000024','dumbbell-hip-thrust','Dumbbell hip thrust','hinge',array['glutes']::text[],array['hamstrings']::text[],array['dumbbell']::text[],'external','Use a stable bench for upper-back support and secure the dumbbell at the hip crease. Drive through the feet to extend the hips without overextending the back. Record the single dumbbell load.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000025','push-up','Push-up','horizontal_push',array['chest']::text[],array['triceps','shoulders','trunk']::text[],array['bodyweight']::text[],'bodyweight','Keep the trunk braced. Lower the chest toward the floor with elbows controlled, then press away. Stop before technique breaks down. Track reps without invented external load.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000026','band-row','Standing band row','horizontal_pull',array['back']::text[],array['biceps']::text[],array['band']::text[],'external','Use a secure anchor at torso height and inspect the band. Pull toward the ribs with a steady trunk, then release slowly. Record band identity and setup; do not convert tension to kilograms.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000027','band-rdl','Band Romanian deadlift','hinge',array['hamstrings','glutes']::text[],array['back']::text[],array['band']::text[],'external','Stand securely on the middle of the band. With knees soft, hinge the hips back, then stand tall against tension. Inspect the band. Record band identity and setup, not an invented kilogram load.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000028','standing-calf-raise','Standing calf raise','calf',array['calves']::text[],array[]::text[],array['bodyweight']::text[],'bodyweight','Stand on level ground near stable support. Raise your heels and lower slowly without bouncing. Track reps; no external load is assumed.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000029','band-leg-curl','Lying band leg curl','knee_flexion',array['hamstrings']::text[],array[]::text[],array['band']::text[],'external','Use a secure low anchor and appropriate ankle attachment. Lie face down, bend the knee against band tension, then extend slowly. Record band and setup, not kilograms.',60,120,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
insert into public.exercises(id,slug,name,movement_pattern,primary_muscles,secondary_muscles,equipment,loading_mode,technique_notes,default_rest_min_seconds,default_rest_max_seconds,evidence_source_ids) values ('20000000-0000-4000-8000-000000000030','pull-up','Pull-up','vertical_pull',array['back']::text[],array['biceps']::text[],array['bodyweight']::text[],'bodyweight','Use a secure overhead bar. Pull the chest upward with a steady trunk and lower with control. Avoid swinging. Track bodyweight reps without invented external load.',120,180,array['10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000008']::uuid[]);
